def doc(title,body):return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="application-version" content="0.10.0"><title>'+esc(title)+'</title><style>'+css+'</style></head><body><main>'+body+'<footer>ALIEN · HORS DES OMBRES — V0.10.0 · Livraison locale du 29 septembre 2026.<br>Adaptation non officielle. Textes et plans de jeu originaux ; assets procéduraux provisoires. Aucune publication ou fusion native annoncée.</footer></main></body></html>'
