 out=[f'<svg class="plan" viewBox="-20 0 1140 {height}" role="img" aria-label="Plan reconstruit de {esc(r["name"])}">','<rect x="0" y="42" width="1100" height="176.4" fill="#122d32" stroke="#668478"/>']
 for i in range(1,10):out.append(f'<path d="M{110*i} 42V218" stroke="#406456" opacity=".3"/>')
 for p in r['props']:
  d=props[p['type']];w=d['width']*sx;out.append(f'<rect x="{p["x"]*sx-w/2:.2f}" y="{Y(p["y"]-18):.2f}" width="{w:.2f}" height="35.3" fill="{"#819786" if p.get("solid") else "#426361"}" opacity=".65"/>')
 for w in r['walls']:out.append(f'<rect class="wall" x="{w["x"]*sx:.2f}" y="{Y(w["y"]):.2f}" width="{max(3,w["w"]*sx):.2f}" height="{w["h"]*.98:.2f}" fill="#d4c295"/>')
 for i,p in enumerate(r['portals'],1):
  x=p['x']*sx;y=Y(p['y']);out += [f'<circle cx="{x:.2f}" cy="{y:.2f}" r="9" fill="#aaccbd" stroke="#071820"/>',f'<text x="{x:.2f}" y="{y+4:.2f}" text-anchor="middle" font-size="12" fill="#081e22">{i}</text>']
 for a in D['interactables']:
  if a['room']==r['id']:out.append(f'<rect x="{a["x"]*sx-3:.2f}" y="{Y(a["y"])-3:.2f}" width="6" height="6" fill="#b1d0cf"/>')
 for p in r['nodes']:out.append(f'<circle cx="{p["x"]*sx:.2f}" cy="{Y(p["y"]):.2f}" r="3" fill="#e7b67b"/>')
 out += ['<text x="0" y="26" font-size="12" fill="#9ab5a9">MUR ARRIÈRE / y = 0</text>','<text x="0" y="248" font-size="12" fill="#9ab5a9">CIRCULATION AVANT / y = 180 — profondeur amplifiée pour la lecture</text>','</svg>']
 return ''.join(out)
